_FULL_UNIVERSE: list[str] | None = None


def get_all_tickers() -> list[str]:
    global _FULL_UNIVERSE
    if _FULL_UNIVERSE is None:
        seen: set[str] = set()
        for lst in GICS_SECTORS.values():
            for t in lst:
                seen.add(t)
        for lst in THEMATIC_GROUPS.values():
            for t in lst:
                seen.add(t)
        _FULL_UNIVERSE = sorted(seen)
    return list(_FULL_UNIVERSE)


UNIVERSE_MAP: dict = dict(GICS_SECTORS)  # type: ignore


def resolve_group(name: str) -> list[str] | None:
    name = name.lower().replace("-", "_").replace(" ", "_")
    if name in UNIVERSE_MAP:
        return UNIVERSE_MAP[name]
    if name in THEMATIC_GROUPS:
        return THEMATIC_GROUPS[name]
    if name in SECTOR_ALIASES:
        return resolve_group(SECTOR_ALIASES[name])
    return None


def list_groups() -> list[str]:
    return sorted(UNIVERSE_MAP.keys()) + sorted(THEMATIC_GROUPS.keys())
